<?php
require __DIR__ . '/_init.php'; $current = require_user();
$event = engine('GET', '/v1/logs/' . uuid(field($_GET, 'id', 36)));
panel_header('Detalle del evento', 'eventos', $current);
?><a class="back-link" href="<?= e(url('eventos.php')) ?>">← Volver al explorador</a><section class="card detail-card"><div class="detail-heading"><?= badge($event['severity']) ?><code><?= e($event['id']) ?></code></div><dl class="detail-grid"><div><dt>Fecha del evento</dt><dd><?= e(date_label($event['timestamp'])) ?></dd></div><div><dt>Fecha de recepción</dt><dd><?= e(date_label($event['received_at'])) ?></dd></div><div><dt>Origen</dt><dd><?= e($event['source']) ?></dd></div><div><dt>Servicio</dt><dd><?= e($event['service'] ?? 'Sin servicio') ?></dd></div></dl><h2>Mensaje</h2><pre><?= e($event['message']) ?></pre><h2>Atributos JSON</h2><pre class="json-block"><?= e(json_encode((object)$event['attributes'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR)) ?></pre><form method="post" action="<?= e(url('analizar.php')) ?>" data-analysis-form><?= csrf_field() ?><input name="log_ids[]" type="hidden" value="<?= e($event['id']) ?>"><button class="button primary" type="submit">✧ Analizar este evento</button><p class="analysis-progress" role="status" hidden>Preparando diagnóstico…</p></form></section><?php panel_footer(); ?>
